const visual = {
  prepare: function (input) {
    var texts = [
      '单位换算表',
      '换算项目',
      '换算算式',
      '结果',
      '72 km/h → m/s',
      '72 ÷ 3.6 = 20.0',
      '20.0 m/s',
      '按题意：72 ÷ 3.6；结果保留三位有效数字。'
    ];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var tableW = Math.min(680, Math.max(280, W - 56));
    var tableX = (W - tableW) / 2;
    var tableY = 88;
    var headerH = 46;
    var rowH = 64;
    var tableH = headerH + rowH;
    var c0 = tableX + tableW * 0.30;
    var c1 = tableX + tableW * 0.68;
    var headY = tableY + headerH / 2 + 6;
    var row1Y = tableY + headerH + rowH / 2 + 6;
    var grid = [];
    grid = grid.concat(visualSdk.polyline([[tableX, tableY], [tableX + tableW, tableY], [tableX + tableW, tableY + tableH], [tableX, tableY + tableH], [tableX, tableY]]));
    grid = grid.concat(visualSdk.polyline([[tableX, tableY + headerH], [tableX + tableW, tableY + headerH]]));
    grid = grid.concat(visualSdk.polyline([[c0, tableY], [c0, tableY + tableH]]));
    grid = grid.concat(visualSdk.polyline([[c1, tableY], [c1, tableY + tableH]]));
    function label(text, x, y, size) {
      return { type: 'label', x: x, y: y, text: text, fontSize: size, fill: '#1f2937', align: 'center' };
    }
    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'grid', commands: grid }],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'grid', stroke: '#334155', strokeWidth: 1.5 },
        label('单位换算表', W / 2, 46, 24),
        label('换算项目', tableX + tableW * 0.15, headY, 17),
        label('换算算式', tableX + tableW * 0.49, headY, 17),
        label('结果', tableX + tableW * 0.84, headY, 17),
        label('72 km/h → m/s', tableX + tableW * 0.15, row1Y, 17),
        label('72 ÷ 3.6 = 20.0', tableX + tableW * 0.49, row1Y, 17),
        label('20.0 m/s', tableX + tableW * 0.84, row1Y, 18),
        label('按题意：72 ÷ 3.6；结果保留三位有效数字。', W / 2, tableY + tableH + 38, 16)
      ]}
    };
  }
};
